private static void rightRotate(TreeNode targetNode) {
    TreeNode parentNode = targetNode.getParent();
    TreeNode childNode = targetNode.getLeftChild();
    TreeNode grandChildNode = childNode.getRightChild();
    if(parentNode == null) {
        redBlackTree = childNode;
        childNode.setParent(null);
        childNode.setRightChild(targetNode);
        targetNode.setParent(childNode);
        targetNode.setLeftChild(grandChildNode);
        grandChildNode.setParent(targetNode);
    } else if(targetNode.getRecord() > parentNode.getRecord()) {
        parentNode.setRightChild(childNode);
        childNode.setParent(parentNode);
        childNode.setRightChild(targetNode);
        targetNode.setParent(childNode);
        targetNode.setLeftChild(grandChildNode);
        grandChildNode.setParent(targetNode);
    } else {
        parentNode.setLeftChild(childNode);
        childNode.setParent(parentNode);
        childNode.setRightChild(targetNode);
        targetNode.setParent(childNode);
        targetNode.setLeftChild(grandChildNode);
        grandChildNode.setParent(targetNode);
    }
}

private static TreeNode searchTree(TreeNode node, int record) {
    if(node.getRecord() == null) {
        return null;
    }
    if(record == node.getRecord()) {
        return node;
    }
    if(record < node.getRecord()) {
        return searchTree(node.getLeftChild(), record);
    }
    return searchTree(node.getRightChild(), record);
}

private static void deleteNode(TreeNode targetNode) {
    TreeNode replaceNode = null;
    if(targetNode.getLeftChild().getRecord() == null || targetNode.getRightChild().getRecord() == null) {
        replaceNode = targetNode;
    } else {
        replaceNode = targetNode.getRightChild();
        while(replaceNode.getLeftChild().getRecord() != null) {
            replaceNode = replaceNode.getLeftChild();
        }
    }
    TreeNode childNode = null;
    if(replaceNode.getLeftChild().getRecord() != null) {
        childNode = replaceNode.getLeftChild();
    } else {
        childNode = replaceNode.getRightChild();
    }
    childNode.setParent(replaceNode.getParent());
    if(replaceNode.getParent() == null) {
        redBlackTree = replaceNode;
        redBlackTree.setRed(false);
    } else if(replaceNode == replaceNode.getParent().getLeftChild()) {
        replaceNode.getParent().setLeftChild(childNode);
    } else {
        replaceNode.getParent().setRightChild(childNode);
    }
    if(replaceNode != targetNode) {
        targetNode.setRecord(replaceNode.getRecord());
    }
    if(!replaceNode.isRed()) {
        balanceAfterDelete(childNode);
    }
}

private static void balanceAfterDelete(TreeNode targetNode) {
    while((targetNode == null || !targetNode.isRed()) && redBlackTree != targetNode) {
        if(targetNode == targetNode.getParent().getLeftChild()) {
            TreeNode brotherNode = targetNode.getParent().getRightChild();
            if(brotherNode.isRed()) {
                brotherNode.setRed(false);
                targetNode.getParent().setRed(true);
                leftRotate(targetNode.getParent());
                brotherNode = targetNode.getRightChild();
            } else if(!((brotherNode.getLeftChild() != null && brotherNode.getLeftChild().isRed())
                    || (brotherNode.getRightChild() != null && brotherNode.getRightChild().isRed()))) {
                brotherNode.setRed(true);
                targetNode = targetNode.getParent();
            } else if(brotherNode.getRightChild() == null || !brotherNode.getRightChild().isRed()) {
                brotherNode.getLeftChild().setRed(false);
                brotherNode.setRed(true);
                rightRotate(brotherNode);
                brotherNode = targetNode.getParent().getRightChild();
            } else {
                brotherNode.setRed(targetNode.getParent().isRed());
                targetNode.getParent().setRed(false);
                brotherNode.getRightChild().setRed(false);
                leftRotate(targetNode.getParent());
                targetNode = redBlackTree;
                break;
            }
        } else {
            TreeNode brotherNode = targetNode.getParent().getLeftChild();
            if(brotherNode.isRed()) {
                brotherNode.setRed(false);
                targetNode.getParent().setRed(true);
                rightRotate(targetNode.getParent());
                brotherNode = targetNode.getLeftChild();
            } else if(!((brotherNode.getRightChild() != null && brotherNode.getRightChild().isRed())
                    || (brotherNode.getLeftChild() != null && brotherNode.getLeftChild().isRed()))) {
                brotherNode.setRed(true);
                targetNode = targetNode.getParent();
            } else if(brotherNode.getLeftChild() == null || !brotherNode.getLeftChild().isRed()) {
                brotherNode.getRightChild().setRed(false);
                brotherNode.setRed(true);
                leftRotate(brotherNode);
                brotherNode = targetNode.getParent().getLeftChild();
            } else {
                brotherNode.setRed(targetNode.getParent().isRed());
                targetNode.getParent().setRed(false);
                brotherNode.getLeftChild().setRed(false);
                rightRotate(targetNode.getParent());
                targetNode = redBlackTree;
                break;
            }
        }
    }
    targetNode.setRed(false);
}

private static void sortBST(TreeNode node) {
    if(node.getRecord() != null) {
        sortBST(node.getLeftChild());
        allElements.add(node.getRecord());
        sortBST(node.getRightChild());
    }
